package com.example.assets_management.permission.entity;

import com.example.assets_management.permission.enums.PermissionStatus; import com.example.assets_management.permission.util.PermissionKeyValidator; import jakarta.persistence.*; import lombok.*; import org.hibernate.annotations.CreationTimestamp; import org.hibernate.annotations.UpdateTimestamp; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="permissions",uniqueConstraints=@UniqueConstraint(name="uk_permissions_permission_key",columnNames="permission_key")) @Getter @Setter @NoArgsConstructor public class Permission {
 @Id @GeneratedValue(strategy=GenerationType.UUID) @Column(nullable=false,updatable=false) private UUID id;
 @Column(name="permission_key",nullable=false,length=255) private String permissionKey; @Column(name="project",length=80) private String project; @Column(name="application",nullable=false,length=100) private String application; @Column(name="module",nullable=false,length=100) private String module; @Column(name="action",nullable=false,length=100) private String action; @Column(name="code",length=255,unique=true) private String code; @Column(length=255) private String description; @Column(name="is_system",nullable=false) private boolean systemPermission=false; @Column(name="is_active",nullable=false) private boolean active=true; @Enumerated(EnumType.STRING) @Column(name="status",nullable=false,length=20) private PermissionStatus status=PermissionStatus.ACTIVE; @CreationTimestamp @Column(name="created_at",nullable=false,updatable=false) private LocalDateTime createdAt; @UpdateTimestamp @Column(name="updated_at") private LocalDateTime updatedAt;
 private void validateAndSynchronizePermissionKey(){ sync(); }
 @PrePersist @PreUpdate private void sync(){PermissionKeyValidator.validate(permissionKey); project=PermissionKeyValidator.project(permissionKey); application=project; module=PermissionKeyValidator.module(permissionKey); action=PermissionKeyValidator.action(permissionKey); code=permissionKey; if(status==null)status=PermissionStatus.ACTIVE; active=status==PermissionStatus.ACTIVE;}
}
